function communityKindLabel(kind: Community["kind"]): string {
  if (kind === "radio") return "Radio";
  if (kind === "podcast") return "Podcast";
  return "Text";
}

function ProfileMutualCommunities({ profile, communities, currentUserId, onOpenCommunity }: { profile: UserProfile; communities: Community[]; currentUserId: string; onOpenCommunity?: (communityId: string) => void }) {
  const isOwnProfile = profile.id === currentUserId;
  const visible = profile.privacy.showCommunities
    ? communities.filter((community) => {
        if (!userBelongsToCommunity(community, profile.id)) return false;
        return isOwnProfile || userBelongsToCommunity(community, currentUserId);
      })
    : [];

  return (
    <section className="profile-panel profile-communities-panel">
      <header className="profile-panel-header profile-panel-header--compact">
        <h2>{isOwnProfile ? "Communities" : "Mutual communities"}</h2>
        <span className="profile-panel-meta">{visible.length}</span>
      </header>
      {visible.length ? (
        <ul className="profile-community-list">
          {visible.slice(0, 8).map((community) => {
            const roster = ensureCommunityMemberRoster(community, isOwnProfile ? {
              userId: profile.id,
              displayName: profile.displayName,
              username: profile.username,
              status: "online",
              statusText: "Online",
              roleId: community.roles.find((role) => role.systemKey === "owner" || role.name === "Owner")?.id ?? community.roles[0]?.id ?? "owner",
            } : null);
            const member = roster.find((candidate) => candidate.userId === profile.id);
            const role = community.roles.find((candidate) => candidate.id === member?.roleId);
            const roleLabel = community.ownerId === profile.id
              ? (role?.name ?? "Owner")
              : (role?.name ?? "Member");
            const markSrc = resolveCommunityMarkSrc(community);
            const heroSrc = community.bannerUrl?.trim() || markSrc;
            const description = (community.description ?? "").trim()
              || `${communityKindLabel(community.kind)} community · ${roster.length} member${roster.length === 1 ? "" : "s"}`;
            const monogram = getCommunityIconLabel(community.name, community.icon);
            return (
              <li key={community.id}>
                <button
                  type="button"
                  className={`profile-community-card${heroSrc ? " profile-community-card--media" : " profile-community-card--fallback"}`}
                  onClick={() => onOpenCommunity?.(community.id)}
                >
                  <span
                    className="profile-community-card__hero"
                    style={heroSrc ? undefined : { background: `linear-gradient(160deg, ${community.accentColor} 0%, color-mix(in srgb, ${community.accentColor} 42%, #0b1a1a) 100%)` }}
                    aria-hidden="true"
                  >
                    {heroSrc ? (
                      <img src={heroSrc} alt="" draggable={false} referrerPolicy="no-referrer" />
                    ) : (
                      <span className="profile-community-card__monogram">{monogram}</span>
                    )}
                  </span>
                  <span className="profile-community-card__body">
                    <strong className="profile-community-card__title">{community.name}</strong>
                    <span className="profile-community-card__description">{description}</span>
                    <span className="profile-community-card__chips">
                      <span className="profile-community-card__chip">{roleLabel}</span>
                      <span className="profile-community-card__chip">{communityKindLabel(community.kind)}</span>
                    </span>
                    <span className="profile-community-card__cta">Open</span>
                  </span>
                </button>
              </li>
            );
          })}
        </ul>
      ) : (
        <div className="profile-empty-state">
          <AppIcon name="users" size="lg" />
          <strong>
            {profile.privacy.showCommunities
              ? (isOwnProfile ? "No communities yet" : "No mutual communities")
              : "Communities are private"}
          </strong>
          <span>
            {profile.privacy.showCommunities
              ? (isOwnProfile
                ? "Communities you create or join will show up here."
                : "Only communities visible to both accounts can appear here.")
              : "Only communities visible to both accounts can appear here."}
          </span>
        </div>
      )}
    </section>
  );
}

.profile-community-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.profile-community-card {
  --profile-community-card-radius: 28px;
  position: relative;
  min-width: 0;
  min-height: 300px;
  aspect-ratio: 3 / 4;
  display: grid;
  grid-template-rows: 1fr;
  padding: 0;
  overflow: hidden;
  isolation: isolate;
  border: 0;
  border-radius: var(--profile-community-card-radius);
  background: #12181c;
  color: #fff;
  text-align: left;
  cursor: pointer;
  box-shadow:
    0 18px 36px color-mix(in srgb, var(--ink) 16%, transparent),
    0 1px 0 color-mix(in srgb, #fff 10%, transparent) inset;
  transition:
    transform 180ms ease,
    box-shadow 180ms ease;
}

.profile-community-card:hover {
  transform: translateY(-3px);
  box-shadow:
    0 22px 40px color-mix(in srgb, var(--ink) 20%, transparent),
    0 1px 0 color-mix(in srgb, #fff 12%, transparent) inset;
}

.profile-community-card:focus-visible {
  outline: 2px solid var(--picom-aqua);
  outline-offset: 3px;
}

.profile-community-card__hero {
  position: absolute;
  inset: 0;
  z-index: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  background: #1a2428;
}

.profile-community-card__hero img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transform: scale(1.02);
}

.profile-community-card__monogram {
  font-size: clamp(42px, 18vw, 72px);
  font-weight: 900;
  letter-spacing: -0.04em;
  color: color-mix(in srgb, #fff 88%, transparent);
  text-shadow: 0 10px 30px color-mix(in srgb, #000 35%, transparent);
  user-select: none;
}

.profile-community-card__body {
  position: relative;
  z-index: 1;
  align-self: end;
  display: grid;
  gap: 10px;
  padding: 22px 18px 18px;
  background:
    linear-gradient(
      180deg,
      transparent 0%,
      color-mix(in srgb, #0b1012 42%, transparent) 28%,
      color-mix(in srgb, #0b1012 88%, transparent) 72%,
      #0b1012 100%
    );
  backdrop-filter: blur(0.5px);
}

.profile-community-card__title {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #fff;
  font-size: 22px;
  font-weight: 850;
  letter-spacing: -0.03em;
  line-height: 1.15;
}

.profile-community-card__description {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
  min-height: 3.6em;
  color: color-mix(in srgb, #fff 78%, transparent);
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1.45;
}

.profile-community-card__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.profile-community-card__chip {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 0 11px;
  border-radius: 999px;
  background: color-mix(in srgb, #fff 14%, transparent);
  color: color-mix(in srgb, #fff 92%, transparent);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.01em;
}

.profile-community-card__cta {
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 44px;
  margin-top: 4px;
  border-radius: 999px;
  background: #fff;
  color: #1a1f24;
  font-size: 14px;
  font-weight: 850;
  letter-spacing: -0.01em;
  box-shadow: 0 8px 18px color-mix(in srgb, #000 28%, transparent);
  transition: background 140ms ease, transform 140ms ease;
}

.profile-community-card:hover .profile-community-card__cta {
  background: #f4f6f7;
}

.profile-community-card:active .profile-community-card__cta {
  transform: translateY(1px);
}
